end $function$

;

CREATE OR REPLACE FUNCTION public.lg_callback_ingest(p_token_hash text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 cred jsonb; act text; p text; c text; cn text; tz text; d date; k text; sid uuid; obs timestamptz;
 run public.lg_sync_runs%rowtype; r jsonb; oldj jsonb; v_hash text; chash text; idx integer; n bigint; nchunks integer;
 sc text; op text; opkind text; code integer; created timestamptz; finished timestamptz; f text; expected_class text; text_class text; code_class text;
 latest timestamptz; stamp timestamptz:=clock_timestamp(); ack jsonb; metrics record; g record; av numeric; ident text; dr text;
 mode text; base_sid uuid; latest_sid uuid; affected bigint:=0; final_status text;
 callback_at timestamptz; callback_day date; envelope jsonb; stale bigint:=0; days date[]; rebuilt date[]:='{}';
 previous_setting text:=coalesce(current_setting('lg_sync.writing',true),'');
begin
 select allowed_scopes into cred from public.lg_sync_credentials where token_hash=p_token_hash and not revoked and expires_at>now();
 if cred is null then raise exception 'LG_AUTH_INVALID'; end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or p_payload->>'source_system' is distinct from 'LG' then raise exception 'LG_INVALID_PAYLOAD'; end if;
 act:=p_payload->>'action';
 if act is null or act not in ('callback_begin','callback_chunk','callback_finish') then raise exception 'LG_INVALID_ACTION'; end if;
 act:=substring(act from 10);
 if p_payload ?| array['stat_date','capture_date','sync_mode','base_snapshot_id'] then raise exception 'LG_INVALID_CALLBACK'; end if;
 p:=p_payload->>'platform'; c:=p_payload->>'country_code'; k:=p_payload->>'order_kind';
 if public.lg_platform_country(p) is null or public.lg_platform_country(p) is distinct from c or (act<>'pending_dates' and k is null) or (k is not null and k not in ('recharge','withdraw')) then raise exception 'LG_INVALID_SCOPE'; end if;
 if not exists(select 1 from jsonb_array_elements(cred) a where a->>'platform'=p and a->>'country_code'=c) then raise exception 'LG_SCOPE_DENIED'; end if;
 tz:=public.lg_country_timezone(c); cn:=case c when 'PH' then '菲律宾' when 'ID' then '印尼' when 'PK' then '巴基斯坦' end;
 if coalesce(p_payload->>'callback_date','') !~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' or coalesce(p_payload->>'observed_at','') !~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|\+00:00)$' then raise exception 'LG_INVALID_DATE'; end if;
 begin
  d:=(p_payload->>'callback_date')::date; sid:=(p_payload->>'snapshot_id')::uuid; obs:=(p_payload->>'observed_at')::timestamptz;
 exception when others then raise exception 'LG_INVALID_DATE'; end;
 if sid is null or obs>clock_timestamp()+interval '5 minutes' or d>=(obs at time zone tz)::date then raise exception 'LG_INVALID_OBSERVED_AT'; end if;
 callback_day:=d; mode:='callback';
 envelope:=jsonb_build_object('source_system','LG','platform',p,'country_code',c,'order_kind',k,'callback_date',d,'snapshot_id',sid,'observed_at',p_payload->>'observed_at');
 if act='begin' then
  if coalesce(p_payload->>'expected_count','') !~ '^[0-9]{1,9}$' or coalesce(p_payload->>'expected_chunks','') !~ '^[0-9]{1,6}$' or coalesce(p_payload->>'fetched_count','') !~ '^[0-9]{1,9}$' or not(p_payload ? 'source_total') or (p_payload->>'source_total' is not null and (p_payload->>'source_total') !~ '^[0-9]{1,9}$') then raise exception 'LG_INVALID_COUNTS'; end if;
  n:=(p_payload->>'expected_count')::bigint; nchunks:=(p_payload->>'expected_chunks')::integer;
  if (p_payload->>'fetched_count')::bigint is distinct from n or (p_payload->>'source_total')::bigint is distinct from n or nchunks>100000 or (n=0 and nchunks<>0) or (n>0 and (nchunks<1 or nchunks>n)) then raise exception 'LG_INCOMPLETE_SOURCE'; end if;
  v_hash:=encode(sha256(convert_to((p_payload-'action')::text,'UTF8')),'hex');
  insert into public.lg_sync_runs(snapshot_id,platform,country_code,stat_date,order_kind,observed_at,expected_count,expected_chunks,source_total,fetched_count,begin_hash,sync_mode,base_snapshot_id)
  values(sid,p,c,d,k,obs,n,nchunks,(p_payload->>'source_total')::bigint,(p_payload->>'fetched_count')::bigint,v_hash,mode,base_sid) on conflict(snapshot_id) do nothing;
  select * into run from public.lg_sync_runs where snapshot_id=sid for update;
  if run.begin_hash<>v_hash then raise exception 'LG_SNAPSHOT_CONFLICT'; end if;
  return envelope || jsonb_build_object('ok',true,'source_system','LG','snapshot_id',sid,'status',case when run.status='callback' then 'published' else run.status end,'expected_count',run.expected_count,'expected_chunks',run.expected_chunks,'observed_at',p_payload->>'observed_at');
 end if;
 -- finish shares AR's global lock BEFORE the per-run row lock and report row locks.
 if act='finish' then perform pg_advisory_xact_lock(193901,20260919); end if;
 select * into run from public.lg_sync_runs where snapshot_id=sid for update;
 if not found then raise exception 'LG_SNAPSHOT_NOT_FOUND'; end if;
 if (run.platform,run.country_code,run.stat_date,run.order_kind,run.observed_at) is distinct from (p,c,d,k,obs) then raise exception 'LG_SNAPSHOT_CONFLICT'; end if;
 if run.sync_mode<>mode or run.base_snapshot_id is distinct from base_sid then raise exception 'LG_SNAPSHOT_CONFLICT'; end if;
 if act='chunk' then
  if coalesce(p_payload->>'chunk_index','') !~ '^[0-9]{1,6}$' or jsonb_typeof(p_payload->'orders') is distinct from 'array' then raise exception 'LG_INVALID_CHUNK'; end if;
  idx:=(p_payload->>'chunk_index')::integer; n:=jsonb_array_length(p_payload->'orders');
  if idx>=run.expected_chunks or n<1 or n>2000 then raise exception 'LG_INVALID_CHUNK'; end if;
  v_hash:=encode(sha256(convert_to((p_payload->'orders')::text,'UTF8')),'hex');
  select content_hash into chash from public.lg_sync_chunks where snapshot_id=sid and chunk_index=idx;
  if found then
   if chash<>v_hash then raise exception 'LG_CHUNK_CONFLICT'; end if;
   return envelope || jsonb_build_object('ok',true,'source_system','LG','snapshot_id',sid,'chunk_index',idx,'status','unchanged','order_count',n);
  end if;
  if run.status<>'collecting' then raise exception 'LG_SNAPSHOT_CLOSED'; end if;
  for r in select value from jsonb_array_elements(p_payload->'orders') loop
   if jsonb_typeof(r) is distinct from 'object' or not(r ?& array['order_no','member_id','status_code','status_text','status_class','order_amount','actual_amount','metric_amount','created_at','finished_at','paid_at','operator_name','operator_kind','handle_seconds','third_party','raw_channel','mapping_code','payment_method','merchant_name','raw'])
    or coalesce(r->>'order_no','') in ('','-','--','---','----','null','None') or length(r->>'order_no')>200 or coalesce(r->>'status_class','') not in ('success','pending','rejected','unknown')
    or coalesce(r->>'operator_kind','') not in ('auto','manual','unknown') or jsonb_typeof(r->'raw') is distinct from 'object' then raise exception 'LG_INVALID_ORDER'; end if;
   if mode='callback' and ((r->'member_id') is distinct from 'null'::jsonb or exists(
    select 1 from jsonb_object_keys(r->'raw') x where x not in (
    'orderAmount','amount','realAmount','actualAmount','payAmount','callbackAmount','feeAmount','giveAmount','money','status',
    'createTime','callbackTime','operatorAt','operateAt','operateTime','updateTime','updatedAt','createdAt','created_at','createAt','orderCreateTime','orderCreatedAt','applyTime'))) then raise exception 'LG_INVALID_PRIVATE_FIELDS'; end if;
   if exists(select 1 from jsonb_object_keys(r) x where x not in
    ('order_no','member_id','status_code','status_text','status_class','order_amount','actual_amount','metric_amount','created_at','finished_at','paid_at','operator_name','operator_kind','handle_seconds','third_party','raw_channel','mapping_code','payment_method','merchant_name','raw'))
    or exists(select 1 from jsonb_each(r->'raw') e where jsonb_typeof(e.value) not in ('string','number','null')) then raise exception 'LG_INVALID_PRIVATE_FIELDS'; end if;
   foreach f in array array['order_no','status_text','operator_name','third_party','raw_channel','mapping_code','payment_method','merchant_name'] loop
    if jsonb_typeof(r->f) is distinct from 'string' or length(r->>f)>500 or (r->>f) ~ '[[:cntrl:]]' then raise exception 'LG_INVALID_ORDER'; end if;
   end loop;
   if jsonb_typeof(r->'member_id') not in ('string','null') or length(r->>'member_id')>200 then raise exception 'LG_INVALID_ORDER'; end if;
   foreach f in array array['order_amount','actual_amount','metric_amount'] loop
    if jsonb_typeof(r->f) not in ('string','null') or (r->>f is not null and (r->>f) !~ '^-?[0-9]{1,30}(\.[0-9]{1,18})?$') then raise exception 'LG_INVALID_AMOUNT'; end if;
   end loop;
   if r->>'status_code' is not null and (r->>'status_code') !~ '^-?[0-9]{1,9}$' then raise exception 'LG_INVALID_ORDER'; end if;
   code:=(r->>'status_code')::integer; sc:=regexp_replace(r->>'status_text','\s+','','g');
   text_class:=case when sc='已支付' then 'success' when sc in ('待支付','支付中') then 'pending' when sc in ('支付失败','已取消','取消','已冲正','冲正','已驳回','驳回','已罚没','罚没') then 'rejected' else 'unknown' end;
   code_class:=case when code=2 then 'success' when k='withdraw' and code in (0,1) then 'pending' when k='withdraw' and code>=3 then 'rejected' else 'unknown' end;
   if text_class<>'unknown' and code_class<>'unknown' and text_class<>code_class then raise exception 'LG_INVALID_STATUS'; end if;
   expected_class:=case when text_class<>'unknown' then text_class else code_class end;
   if r->>'status_class'<>expected_class then raise exception 'LG_INVALID_STATUS'; end if;
   op:=btrim(replace(replace(r->>'operator_name',chr(8203),''),chr(65279),''));
   opkind:=case when lower(op) in ('','----','---','--','-','null','none','n/a') then 'unknown' when lower(op) like '%system%' or lower(op)='sys' then 'auto' else 'manual' end;
   if r->>'operator_kind'<>opkind then raise exception 'LG_INVALID_OPERATOR'; end if;
   if coalesce(r->>'created_at','') !~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|\+00:00)$'
    or (r->>'finished_at' is not null and (r->>'finished_at') !~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|\+00:00)$') then raise exception 'LG_INVALID_ORDER_DATE'; end if;
   begin created:=(r->>'created_at')::timestamptz; finished:=(r->>'finished_at')::timestamptz; exception when others then raise exception 'LG_INVALID_ORDER_DATE'; end;
   if r->>'paid_at' is not null then
    if (r->>'paid_at') !~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|\+00:00)$' or expected_class<>'success' then raise exception 'LG_INVALID_ORDER_DATE'; end if;
    begin perform (r->>'paid_at')::timestamptz; exception when others then raise exception 'LG_INVALID_ORDER_DATE'; end;
   end if;
   callback_at:=private.lg_callback_timestamp(r->'raw'->'callbackTime',tz);
   if callback_at is null or (callback_at at time zone tz)::date<>callback_day or callback_at<created
    or (expected_class='success' and (r->>'paid_at')::timestamptz is distinct from callback_at)
    or (expected_class<>'success' and r->>'paid_at' is not null) then raise exception 'LG_INVALID_CALLBACK_TIME'; end if;
   if r->>'handle_seconds' is not null and (r->>'handle_seconds') !~ '^[0-9]{1,9}$' then raise exception 'LG_INVALID_ORDER'; end if;
   select order_json into oldj from public.lg_order_stage where snapshot_id=sid and order_no=r->>'order_no';
   if found and oldj<>r then raise exception 'LG_ORDER_CONFLICT'; end if;
   insert into public.lg_order_stage(snapshot_id,order_no,order_json,content_hash)
   values(sid,r->>'order_no',r,encode(sha256(convert_to(r::text,'UTF8')),'hex')) on conflict(snapshot_id,order_no) do nothing;
  end loop;
  if (select count(*) from public.lg_order_stage where snapshot_id=sid)>run.expected_count then raise exception 'LG_TOO_MANY_ORDERS'; end if;
  insert into public.lg_sync_chunks(snapshot_id,chunk_index,content_hash,order_count) values(sid,idx,v_hash,n);
  return envelope || jsonb_build_object('ok',true,'source_system','LG','snapshot_id',sid,'chunk_index',idx,'status','accepted','order_count',n);
 end if;
 if run.status='callback' then return run.receipt || jsonb_build_object('status','unchanged'); end if;
 if run.status<>'collecting' then raise exception 'LG_SNAPSHOT_CLOSED'; end if;
 if (select count(*) from public.lg_sync_chunks where snapshot_id=sid)<>run.expected_chunks
  or (select coalesce(sum(order_count),0) from public.lg_sync_chunks where snapshot_id=sid)<>run.expected_count
  or (select count(*) from public.lg_order_stage where snapshot_id=sid)<>run.expected_count
  or exists(select 1 from generate_series(0,run.expected_chunks-1) i where not exists(select 1 from public.lg_sync_chunks ch where ch.snapshot_id=sid and ch.chunk_index=i)) then raise exception 'LG_INCOMPLETE_SNAPSHOT'; end if;
 -- Check both the order and its complete creation-day observation. This also
 -- prevents an older callback resurrecting an order absent from a later full day.
 delete from public.lg_order_stage s where s.snapshot_id=sid and (
  exists(select 1 from public.lg_orders o where o.platform=p and o.order_kind=k and o.order_no=s.order_no and o.observed_at>=obs)
  or exists(select 1 from public.lg_sync_runs h where h.platform=p and h.order_kind=k
   and h.stat_date=((s.order_json->>'created_at')::timestamptz at time zone tz)::date
   and h.status in ('published','live') and h.observed_at>=obs));
 get diagnostics stale=row_count;
 -- Keep the existing immutable creation-day scope boundary. A correction to
 -- another day needs an explicit repair, not a silently displaced daily cohort.
 if exists(select 1 from public.lg_order_stage s join public.lg_orders o on o.platform=p and o.order_kind=k and o.order_no=s.order_no
  where s.snapshot_id=sid and o.stat_date<>((s.order_json->>'created_at')::timestamptz at time zone tz)::date) then raise exception 'LG_ORDER_SCOPE_CONFLICT'; end if;
 select array_agg(distinct ((s.order_json->>'created_at')::timestamptz at time zone tz)::date) into days from public.lg_order_stage s where s.snapshot_id=sid;
 insert into public.lg_orders(platform,country_code,stat_date,order_kind,order_no,member_id,status_code,status_text,status_class,order_amount,actual_amount,metric_amount,created_at,finished_at,paid_at,operator_name,operator_kind,handle_seconds,third_party,raw_channel,mapping_code,payment_method,merchant_name,raw,snapshot_id,observed_at,updated_at)
 select p,c,(x.created_at at time zone tz)::date,k,x.order_no,x.member_id,x.status_code,x.status_text,x.status_class,x.order_amount,x.actual_amount,x.metric_amount,x.created_at,x.finished_at,x.paid_at,x.operator_name,x.operator_kind,x.handle_seconds,
 coalesce(nullif(case when k='withdraw' then x.merchant_name end,''),nullif(x.third_party,''),nullif(x.raw_channel,''),nullif(x.payment_method,''),'未知'),x.raw_channel,case when k='withdraw' then '' else x.mapping_code end,x.payment_method,x.merchant_name,x.raw,sid,obs,stamp
 from public.lg_order_stage s cross join lateral jsonb_to_record(s.order_json) as x(order_no text,member_id text,status_code integer,status_text text,status_class text,order_amount numeric,actual_amount numeric,metric_amount numeric,created_at timestamptz,finished_at timestamptz,paid_at timestamptz,operator_name text,operator_kind text,handle_seconds integer,third_party text,raw_channel text,mapping_code text,payment_method text,merchant_name text,raw jsonb) where s.snapshot_id=sid
 on conflict(platform,order_kind,order_no) do update set
 member_id=excluded.member_id,
 status_code=excluded.status_code,
 status_text=excluded.status_text,
 status_class=excluded.status_class,
 order_amount=excluded.order_amount,
 actual_amount=excluded.actual_amount,
 metric_amount=excluded.metric_amount,
 created_at=excluded.created_at,
 finished_at=excluded.finished_at,
 paid_at=excluded.paid_at,
 operator_name=excluded.operator_name,
 operator_kind=excluded.operator_kind,
 handle_seconds=excluded.handle_seconds,
 third_party=excluded.third_party,
 raw_channel=excluded.raw_channel,
 mapping_code=excluded.mapping_code,
 payment_method=excluded.payment_method,
 merchant_name=excluded.merchant_name,
 raw=excluded.raw,
 snapshot_id=excluded.snapshot_id,
 observed_at=excluded.observed_at,
 updated_at=excluded.updated_at
 where excluded.observed_at > lg_orders.observed_at and row(lg_orders.member_id,lg_orders.status_code,lg_orders.status_text,lg_orders.status_class,lg_orders.order_amount,lg_orders.actual_amount,lg_orders.metric_amount,lg_orders.created_at,lg_orders.finished_at,lg_orders.paid_at,lg_orders.operator_name,lg_orders.operator_kind,lg_orders.handle_seconds,lg_orders.third_party,lg_orders.raw_channel,lg_orders.mapping_code,lg_orders.payment_method,lg_orders.merchant_name,lg_orders.raw) is distinct from row(excluded.member_id,excluded.status_code,excluded.status_text,excluded.status_class,excluded.order_amount,excluded.actual_amount,excluded.metric_amount,excluded.created_at,excluded.finished_at,excluded.paid_at,excluded.operator_name,excluded.operator_kind,excluded.handle_seconds,excluded.third_party,excluded.raw_channel,excluded.mapping_code,excluded.payment_method,excluded.merchant_name,excluded.raw);
 get diagnostics affected=row_count;
 -- A newer identical observation is still a freshness watermark. It does not
 -- change updated_at or changed_count, and prevents delayed stale callbacks.
 update public.lg_orders o set observed_at=obs
 where o.platform=p and o.order_kind=k and o.observed_at<obs
 and exists(select 1 from public.lg_order_stage s where s.snapshot_id=sid and s.order_no=o.order_no);
 if affected>0 then
  foreach d in array coalesce(days,'{}'::date[]) loop
   if exists(select 1 from public.lg_sync_runs h where h.platform=p and h.order_kind=k and h.stat_date=d and h.status in ('published','live')) then
 delete from public.lg_success_daily where platform=p and stat_date=d and order_kind=k;
 insert into public.lg_success_daily(platform,country_code,stat_date,order_kind,scope_type,third_party,raw_channel,mapping_code,total_count,success_count,failed_count,pending_count,unknown_count,total_amount,success_amount,snapshot_id,observed_at,updated_at)
 select p,c,d,k,case when grouping(third_party)=1 then 'platform' when grouping(raw_channel)=1 then 'third_party' else 'channel' end,
 coalesce(third_party,''),coalesce(raw_channel,''),coalesce(mapping_code,''),count(*),count(*) filter(where status_class='success'),count(*) filter(where status_class='rejected'),count(*) filter(where status_class='pending'),count(*) filter(where status_class='unknown'),sum(order_amount),sum(order_amount) filter(where status_class='success'),sid,obs,stamp
 from public.lg_orders where platform=p and stat_date=d and order_kind=k group by grouping sets((),(third_party),(third_party,raw_channel,mapping_code));

 perform set_config('lg_sync.writing','on',true);
 if k='withdraw' then
  select count(*) as total,count(*) filter(where status_class='success') as success,count(*) filter(where status_class='rejected') as rejected,count(*) filter(where status_class='pending') as pending,count(*) filter(where status_class='unknown') as unknown,
  count(*) filter(where operator_kind='auto') as auto_count,count(*) filter(where operator_kind='manual') as manual_count,count(*) filter(where operator_kind='unknown') as unknown_operator_count,
  coalesce(sum(handle_seconds) filter(where handle_seconds>0),0) as secs,count(*) filter(where handle_seconds>0) as hc into metrics from public.lg_orders where platform=p and stat_date=d and order_kind=k;
  av:=case when metrics.hc>0 then round(metrics.secs::numeric/metrics.hc,6) else 0 end;
  ident:=encode(sha256(convert_to('auto|'||d::text||'|LG|'||cn||'|'||p,'UTF8')),'hex');
  delete from public.auto_withdraw_daily a where a.data_date=d and a.country=cn and upper(a.platform)=p and public.lg_is_owned_report(to_jsonb(a),false);
  insert into public.auto_withdraw_daily(id,data_date,country,platform,total,success,rejected,auto_count,manual_count,avg_seconds,avg_time_text,source_sheet,raw,source_updated_at,updated_at)
  values(ident,d,cn,p,metrics.total,metrics.success,metrics.rejected,metrics.auto_count,metrics.manual_count,av,round(av)::text||'秒','LG_DIRECT',jsonb_build_object('system','LG','system_name','LG','direct_source','lg-sync-v1','snapshot_id',sid,'pending_count',metrics.pending,'unknown_count',metrics.unknown,'unknown_operator_count',metrics.unknown_operator_count,'totalHandleSeconds',metrics.secs,'handleCount',metrics.hc),obs,stamp);
  delete from public.withdraw_operator_daily a where a.data_date=d and a.country=cn and upper(a.platform)=p and public.lg_is_owned_report(to_jsonb(a),false);
  for g in select operator_name,count(*) as processed,count(*) filter(where status_class='rejected') as rejected,coalesce(sum(handle_seconds) filter(where handle_seconds>0),0) as secs,count(*) filter(where handle_seconds>0) as hc from public.lg_orders where platform=p and stat_date=d and order_kind=k and operator_kind='manual' group by operator_name loop
   av:=case when g.hc>0 then round(g.secs::numeric/g.hc,6) else 0 end;
   ident:=encode(sha256(convert_to('operator|'||d::text||'|LG|'||cn||'|'||p||'|'||g.operator_name,'UTF8')),'hex');
   insert into public.withdraw_operator_daily(id,data_date,country,platform,account,processed,rejected,avg_seconds,avg_time_text,source_sheet,raw,source_updated_at,updated_at)
   values(ident,d,cn,p,g.operator_name,g.processed,g.rejected,av,round(av)::text||'秒','LG_DIRECT',jsonb_build_object('system','LG','system_name','LG','direct_source','lg-sync-v1','snapshot_id',sid,'totalHandleSeconds',g.secs,'handleCount',g.hc),obs,stamp);
  end loop;
 end if;
 dr:=case k when 'withdraw' then '代付' else '代收' end;
 delete from public.third_party_volume a where a.data_date=d and a.country=cn and upper(a.platform)=p and a.direction=dr and public.lg_is_owned_report(to_jsonb(a),true);
 -- This compatibility volume intentionally keeps the old withdrawal rule (paying OR paid).
 -- Actual all-status success rates live exclusively in lg_success_daily.
 for g in select third_party,mapping_code,count(*) as cnt,round(sum(coalesce(metric_amount,0)),2) as amt from public.lg_orders where platform=p and stat_date=d and order_kind=k
 and (case when k='withdraw' then status_code in(1,2) or regexp_replace(status_text,'\s+','','g') in('支付中','已支付') else status_class='success' end) group by third_party,mapping_code loop
  ident:='lg-direct-'||md5(jsonb_build_array(d,cn,p,dr,g.third_party,g.mapping_code)::text);
  insert into public.third_party_volume(id,sheet_name,source_row,data_date,country,platform,channel,raw_channel,channel_type,direction,amount,count,success_count,failed_count,success_rate,status,raw,updated_at)
  values(ident,'LG_DIRECT',0,d,cn,p,g.third_party,g.third_party,g.mapping_code,dr,g.amt,g.cnt,g.cnt,0,1,'',jsonb_build_object('system','LG','system_name','LG','direct_source','lg-sync-v1','snapshot_id',sid,'third_party',g.third_party,'mapping_code',g.mapping_code,'volume_status_rule',case k when 'withdraw' then 'paying_or_paid' else 'paid_only' end),stamp);
 end loop;
 perform set_config('lg_sync.writing',previous_setting,true);
    rebuilt:=array_append(rebuilt,d);
   end if;
  end loop;
 end if;
 ack:=envelope||jsonb_build_object('ok',true,'status','published','order_count',run.expected_count,'changed_count',affected,'stale_count',stale,
  'coverage','callback_subset','creation_day_complete',false,'rebuilt_dates',to_jsonb(rebuilt));
 update public.lg_sync_runs set status='callback',published_at=stamp,receipt=ack where snapshot_id=sid;
 delete from public.lg_order_stage where snapshot_id=sid;
 return ack;
end $function$

;

CREATE OR REPLACE FUNCTION public.lg_sync_report_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r jsonb; candidates jsonb; k text;
begin
 if current_setting('lg_sync.writing',true)='on' then
  if tg_op='DELETE' then return old; else return new; end if;
 end if;
 candidates:=case when tg_op='INSERT' then jsonb_build_array(to_jsonb(new)) when tg_op='DELETE' then jsonb_build_array(to_jsonb(old)) else jsonb_build_array(to_jsonb(old),to_jsonb(new)) end;
 for r in select value from jsonb_array_elements(candidates) loop
  if not coalesce(public.lg_is_owned_report(r,tg_table_name='third_party_volume'),false) then continue; end if;
  k:=case when tg_table_name<>'third_party_volume' then 'withdraw' when r->>'direction'='代收' then 'recharge' when r->>'direction'='代付' then 'withdraw' end;
  if exists(select 1 from public.lg_sync_runs s where s.status in ('published','live') and s.platform=upper(r->>'platform') and s.stat_date=(r->>'data_date')::date and s.order_kind=k) then return null; end if;
 end loop;
 if tg_op='DELETE' then return old; else return new; end if;
end $function$

;

