create table private.lg_window_cursors (
 platform text not null, country_code text not null, order_kind text not null, stream text not null,
 origin_at timestamptz not null, cursor_at timestamptz not null,
 owner_id uuid, token_hash text, lease_token uuid, lease_expires_at timestamptz,
 active_snapshot_id uuid, updated_at timestamptz not null default clock_timestamp(),
 primary key(platform,country_code,order_kind,stream),
 check(public.lg_platform_country(platform)=country_code), check(order_kind in ('recharge','withdraw')),
 check(stream in ('created','callback')), check(cursor_at>=origin_at),
 check(date_trunc('second',origin_at)=origin_at and date_trunc('second',cursor_at)=cursor_at)
);
create table private.lg_window_runs (
 snapshot_id uuid primary key references public.lg_sync_runs(snapshot_id),
 platform text not null, country_code text not null, order_kind text not null, stream text not null,
 purpose text not null check(purpose in ('advance','recheck')),
 lease_token uuid not null, token_hash text not null, expected_cursor timestamptz not null,
 start_at timestamptz not null, end_at timestamptz not null, observed_at timestamptz not null,
 expected_count bigint not null, expected_chunks integer not null, begin_hash text not null,
